<template>
  <div class="register-page"><div class="register-card"><div class="reg-side"><div class="auth-brand"><span><el-icon><Reading /></el-icon></span><div><b>有为书院</b><small>JOIN THE ACADEMY</small></div></div><div class="reg-copy"><div class="eyebrow light">BEGIN YOUR JOURNEY</div><h1>今天，<br>开始一段<br>新的阅读旅程</h1><p>创建账号，借阅馆藏，参与讨论，完成学习任务。</p></div><div class="reg-tags"><span>馆藏借阅</span><span>在线阅读</span><span>思想社区</span><span>学习任务</span></div></div><div class="reg-form"><div class="auth-heading"><div class="eyebrow">CREATE ACCOUNT</div><h2>创建书院账号</h2><p>选择你的身份，加入有为书院。</p></div><el-form :model="form" ref="formRef" :rules="rules" label-position="top"><el-form-item label="身份"><el-select v-model="form.role" size="large" style="width:100%"><el-option value="USER" label="书院读者"/><el-option value="TEACHER" label="书院教师"/></el-select></el-form-item><el-form-item label="账号" prop="username"><el-input v-model="form.username" size="large" placeholder="请输入账号"/></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" size="large" show-password placeholder="至少 6 位字符"/></el-form-item><el-form-item label="确认密码" prop="confirmPassword"><el-input v-model="form.confirmPassword" size="large" show-password placeholder="再次输入密码"/></el-form-item><el-button type="primary" size="large" round class="reg-btn" @click="register">创建账号</el-button></el-form><div class="auth-switch">已有账号？<router-link to="/login">返回登录</router-link></div></div></div></div>
</template>
<script setup>
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import request from '@/utils/request';import {ElMessage} from 'element-plus'
const router=useRouter(),formRef=ref();const form=reactive({username:'',password:'',confirmPassword:'',role:'USER'});const validatePass=(r,v,cb)=>!v?cb(new Error('请确认密码')):v!==form.password?cb(new Error('两次密码不一致')):cb();const rules={username:[{required:true,message:'请输入账号',trigger:'blur'}],password:[{required:true,min:6,message:'密码至少 6 位',trigger:'blur'}],confirmPassword:[{validator:validatePass,trigger:'blur'}]};const register=()=>formRef.value.validate(valid=>{if(!valid)return;request.post('/register',form).then(res=>{if(res.code==='200'){ElMessage.success('注册成功，请登录');router.push('/login')}else ElMessage.error(res.msg)})})
</script>
<style scoped>
.register-page{min-height:100vh;background:linear-gradient(135deg,#e8eee9,#f7f4ee);display:grid;place-items:center;padding:42px}.register-card{width:min(1050px,100%);min-height:650px;display:grid;grid-template-columns:1.05fr .95fr;background:#fff;border-radius:28px;overflow:hidden;box-shadow:0 30px 90px rgba(20,33,61,.14)}.reg-side{background:linear-gradient(145deg,#0a1f30,#1d5556);color:#fff;padding:42px;display:flex;flex-direction:column}.auth-brand{display:flex;align-items:center;gap:12px}.auth-brand>span{width:42px;height:42px;border-radius:13px;background:rgba(255,255,255,.12);display:grid;place-items:center;font-size:21px}.auth-brand div{display:flex;flex-direction:column;gap:5px}.auth-brand b{font-family:var(--font-serif);font-size:19px}.auth-brand small{font-size:8px;letter-spacing:.16em;color:rgba(255,255,255,.35)}.reg-copy{margin:auto 0}.reg-copy h1{font-family:var(--font-serif);font-size:45px;line-height:1.35;margin:16px 0 20px}.reg-copy p{color:rgba(255,255,255,.55);line-height:1.9}.reg-tags{display:flex;flex-wrap:wrap;gap:8px}.reg-tags span{padding:7px 12px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);font-size:10px;color:rgba(255,255,255,.65)}.reg-form{padding:62px 54px;display:flex;flex-direction:column;justify-content:center}.auth-heading{margin-bottom:26px}.auth-heading h2{font-family:var(--font-serif);font-size:31px;margin:10px 0}.auth-heading p{color:var(--muted);font-size:12px}.reg-btn{width:100%;margin-top:7px}.auth-switch{text-align:center;color:var(--muted);font-size:12px;margin-top:20px}.auth-switch a{color:var(--primary);font-weight:700}@media(max-width:850px){.register-card{grid-template-columns:1fr}.reg-side{display:none}.reg-form{padding:48px 30px}}
</style>
